1	//! A warm checker that answers for the components a session asks about, one request at a time.
2	//!
3	//! The one-shot [`crate::resolve`] roots a single program at every component's file. A Storybook session asks about
4	//! one component per story, so this keeps one `tsc --api` process alive, starts it on the first request, and roots a
5	//! small program at just the requested files: the checker loads what those files import, not the project.
6	//!
7	//! The process runs on its own thread with its own runtime, so a caller on any thread (a NAPI worker, a rayon task)
8	//! never nests runtimes and can bound how long it waits. A failure to start or a crash yields an outcome with no
9	//! components and one diagnostic, never an error; after [`MAX_RESTARTS`] crashes the checker stays down.
10	
11	use std::sync::mpsc;
12	use std::thread::JoinHandle;
13	use std::time::Duration;
14	
15	use caliper_docgen_core::types::semantic::{SemanticOutcome, SemanticProvider, SemanticTarget};
16	use caliper_docgen_tsc_client::Supervisor;
17	use camino::Utf8PathBuf;
18	use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender, unbounded_channel};
19	
20	use crate::rpc::Rpc;
21	use crate::{SUPPORTED_VERSIONS, SemanticRequest, answer_with, supervisor_config};
22	
23	/// Crashes the checker may have before it stays down for the session.
24	const MAX_RESTARTS: u32 = 3;
25	
26	/// Programs one `tsc` process builds before it is replaced. Its memory grows with every program it has loaded
27	/// (measured: antd reached 600 MiB after 50 single-component programs), and a fresh process costs 30 to 70 ms.
28	const MAX_REQUESTS_PER_PROCESS: u32 = 64;
29	
30	/// Resident memory, in MiB, past which a `tsc` process is replaced between requests. Measured single-component programs
31	/// peak at 157 to 612 MiB (antd the highest); a process past this has loaded more than a story session needs.
32	const DEFAULT_MAX_RSS_MIB: u64 = 768;
33	
34	/// How many requests pass between memory checks: each reads the process table, which costs a few milliseconds.
35	const RSS_CHECK_EVERY: u32 = 4;
36	
37	/// How long dropping a checker waits, by default, for its worker to finish a request and stop `tsc`, before leaving the
38	/// worker to finish on its own. Closing a session must not wait for a 60 s request.
39	const DEFAULT_SHUTDOWN_WAIT: Duration = Duration::from_secs(5);
40	
41	/// How a warm [`OnDemand`] checker starts and is kept: where to find `tsc`, how long to wait on it, and when to replace
42	/// its process.
43	#[derive(Debug, Clone)]
44	pub struct OnDemandConfig {
45	    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
46	    pub project_root: Utf8PathBuf,
47	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
48	    pub tsconfig: Option<Utf8PathBuf>,
49	    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
50	    pub tsc_path: Option<Utf8PathBuf>,
51	    /// Bound on each request to the checker, and on its start-up handshake.
52	    pub request_timeout: Duration,
53	    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
54	    pub expected_versions: &'static [&'static str],
55	    /// Resident memory of the `tsc` process, in MiB, past which it is replaced after a request. A request that needs
56	    /// more finishes first: the bound is between requests, not inside one.
57	    pub max_rss_mib: u64,
58	    /// How long dropping the checker waits for a request in progress before it lets the worker finish alone.
59	    pub shutdown_wait: Duration,
60	    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
61	    pub extra_env: Vec<(String, String)>,
62	}
63	
64	impl OnDemandConfig {
65	    /// A configuration for `project_root` with a 60 second request timeout, the supported versions, a 768 MiB memory
66	    /// bound, a 5 second shutdown wait, and no explicit tsconfig or `tsc` path.
67	    pub fn new(project_root: Utf8PathBuf) -> Self {
68	        Self {
69	            project_root,
70	            tsconfig: None,
71	            tsc_path: None,
72	            request_timeout: Duration::from_secs(60),
73	            expected_versions: SUPPORTED_VERSIONS,
74	            max_rss_mib: DEFAULT_MAX_RSS_MIB,
75	            shutdown_wait: DEFAULT_SHUTDOWN_WAIT,
76	            extra_env: Vec::new(),
77	        }
78	    }
79	}
80	
81	/// The resident memory of a process in MiB: `/proc` where it exists, else `ps`. `None` when neither answers.
82	fn resident_mib(pid: u32) -> Option<u64> {
83	    let kib = match std::fs::read_to_string(format!("/proc/{pid}/status")) {
84	        Ok(status) => status
85	            .lines()
86	            .find_map(|line| line.strip_prefix("VmRSS:"))?
87	            .split_whitespace()
88	            .next()?
89	            .parse::<u64>()
90	            .ok()?,
91	        Err(_) => {
92	            let output = std::process::Command::new("ps").args(["-o", "rss=", "-p", &pid.to_string()]).output().ok()?;
93	            String::from_utf8_lossy(&output.stdout).trim().parse::<u64>().ok()?
94	        }
95	    };
96	    Some(kib / 1024)
97	}
98	
99	enum Job {
100	    /// Start the checker now instead of at the first request.
101	    Warm,
102	    Answer {
103	        targets: Vec<SemanticTarget>,
104	        reply: mpsc::SyncSender<SemanticOutcome>,
105	    },
106	}
107	
108	/// A warm `tsc` that answers for the components it is asked about. Dropping it stops the process.
109	pub struct OnDemand {
110	    jobs: Option<UnboundedSender<Job>>,
111	    thread: Option<JoinHandle<()>>,
112	    /// Receives once when the worker has stopped `tsc` and is about to exit.
113	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
114	    shutdown_wait: Duration,
115	}
116	
117	impl OnDemand {
118	    /// Starts the worker thread. The `tsc` process itself starts on the first request, or on [`OnDemand::warm_up`].
119	    pub fn new(config: OnDemandConfig) -> Self {
120	        let shutdown_wait = config.shutdown_wait;
121	        let (jobs, queue) = unbounded_channel();
122	        let (stopped_tx, stopped) = mpsc::channel();
123	        let thread = std::thread::Builder::new()
124	            .name("caliper-tsc".to_string())
125	            .spawn(move || {
126	                worker(config, queue);
127	                stopped_tx.send(()).ok();
128	            })
129	            .ok();
130	        Self {
131	            jobs: thread.as_ref().map(|_| jobs),
132	            thread,
133	            stopped: std::sync::Mutex::new(Some(stopped)),
134	            shutdown_wait,
135	        }
136	    }
137	
138	    /// Starts `tsc` in the background so the first request does not pay for it.
139	    pub fn warm_up(&self) {
140	        if let Some(jobs) = &self.jobs {
141	            jobs.send(Job::Warm).ok();
142	        }
143	    }
144	}
145	
146	impl SemanticProvider for OnDemand {
147	    fn request(&self, targets: Vec<SemanticTarget>) -> mpsc::Receiver<SemanticOutcome> {
148	        let (reply, receiver) = mpsc::sync_channel(1);
149	        match &self.jobs {
150	            Some(jobs) => {
151	                if let Err(refused) = jobs.send(Job::Answer { targets, reply })
152	                    && let Job::Answer { reply, .. } = refused.0
153	                {
154	                    reply.send(SemanticOutcome::unavailable("the checker thread has stopped")).ok();
155	                }
156	            }
157	            None => {
158	                reply.send(SemanticOutcome::unavailable("could not start the checker thread")).ok();
159	            }
160	        }
161	        receiver
162	    }
163	}
164	
165	impl Drop for OnDemand {
166	    fn drop(&mut self) {
167	        // Closing the queue ends the worker loop, which shuts `tsc` down before the thread exits. A worker still inside
168	        // a long request is left to finish it: `tsc` stops when it does, or with this process.
169	        self.jobs.take();
170	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
171	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
172	        if let Some(thread) = self.thread.take()
173	            && stopped
174	        {
175	            thread.join().ok();
176	        }
177	    }
178	}
179	
180	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>) {
181	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
182	        Ok(runtime) => runtime,
183	        Err(error) => {
184	            let reason = format!("could not start an async runtime: {error}");
185	            while let Some(job) = queue.blocking_recv() {
186	                if let Job::Answer { reply, .. } = job {
187	                    reply.send(SemanticOutcome::unavailable(reason.clone())).ok();
188	                }
189	            }
190	            return;
191	        }
192	    };
193	    runtime.block_on(async move {
194	        let mut checker = Checker::default();
195	        while let Some(job) = queue.recv().await {
196	            match job {
197	                Job::Warm => {
198	                    checker.ensure(&config).await.ok();
199	                }
200	                Job::Answer { targets, reply } => {
201	                    reply.send(checker.answer(&config, targets).await).ok();
202	                    // After the reply, so the caller never waits for the memory check or the replacement.
203	                    checker.maintain(&config).await;
204	                }
205	            }
206	        }
207	        if let Some(supervisor) = checker.supervisor.take() {
208	            supervisor.shutdown().await.ok();
209	        }
210	    });
211	}
212	
213	#[derive(Default)]
214	struct Checker {
215	    supervisor: Option<Supervisor>,
216	    /// Compiler options read once from the tsconfig for the running process.
217	    options: Option<serde_json::Value>,
218	    restarts: u32,
219	    /// Requests the running process has answered.
220	    served: u32,
221	    /// Why the checker cannot be used for the rest of the session.
222	    down: Option<String>,
223	}
224	
225	impl Checker {
226	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
227	        if let Some(reason) = &self.down {
228	            return Err(reason.clone());
229	        }
230	        if self.supervisor.as_ref().is_some_and(|supervisor| !supervisor.is_alive()) {
231	            if let Some(dead) = self.supervisor.take() {
232	                dead.shutdown().await.ok();
233	            }
234	            self.options = None;
235	            self.restarts += 1;
236	            if self.restarts > MAX_RESTARTS {
237	                return Err(self.stay_down("the checker kept crashing".to_string()));
238	            }
239	        }
240	        if self.supervisor.is_none() {
241	            let request = SemanticRequest {
242	                project_root: config.project_root.clone(),
243	                tsconfig: config.tsconfig.clone(),
244	                tsc_path: config.tsc_path.clone(),
245	                targets: Vec::new(),
246	                request_timeout: config.request_timeout,
247	                expected_versions: config.expected_versions,
248	                record_to: None,
249	                extra_env: config.extra_env.clone(),
250	                reverse_queries: false,
251	                prepared_options: None,
252	            };
253	            let started = supervisor_config(&request).map_err(|reason| self.stay_down(reason))?;
254	            let supervisor = match Supervisor::spawn(started).await {
255	                Ok(supervisor) => supervisor,
256	                Err(error) => return Err(self.stay_down(error.to_string())),
257	            };
258	            // Initialize the session and read the compiler options once; every request after builds only its program.
259	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
260	            match Rpc::prepare(&supervisor.client(), config.request_timeout, tsconfig).await {
261	                Ok(options) => self.options = Some(options),
