187	                    reply.send(SemanticOutcome::unavailable(reason.clone())).ok();
188	                }
189	            }
190	            return;
191	        }
192	    };
193	    runtime.block_on(async move {
194	        let mut checker = Checker::default();
195	        while let Some(job) = queue.recv().await {
196	            match job {
197	                Job::Warm => {
198	                    checker.ensure(&config).await.ok();
199	                }
200	                Job::Answer { targets, reply } => {
201	                    reply.send(checker.answer(&config, targets).await).ok();
202	                    // After the reply, so the caller never waits for the memory check or the replacement.
203	                    checker.maintain(&config).await;
204	                }
205	            }
206	        }
207	        if let Some(supervisor) = checker.supervisor.take() {
208	            supervisor.shutdown().await.ok();
209	        }
210	    });
211	}
212	
213	#[derive(Default)]
214	struct Checker {
215	    supervisor: Option<Supervisor>,
216	    /// Compiler options read once from the tsconfig for the running process.
217	    options: Option<serde_json::Value>,
218	    restarts: u32,
219	    /// Requests the running process has answered.
220	    served: u32,
221	    /// Why the checker cannot be used for the rest of the session.
222	    down: Option<String>,
223	}
224	
225	impl Checker {
226	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
227	        if let Some(reason) = &self.down {
228	            return Err(reason.clone());
229	        }
230	        if self.supervisor.as_ref().is_some_and(|supervisor| !supervisor.is_alive()) {
231	            if let Some(dead) = self.supervisor.take() {
232	                dead.shutdown().await.ok();
233	            }
234	            self.options = None;
235	            self.restarts += 1;
236	            if self.restarts > MAX_RESTARTS {
237	                return Err(self.stay_down("the checker kept crashing".to_string()));
238	            }
239	        }
240	        if self.supervisor.is_none() {
241	            let request = SemanticRequest {
242	                project_root: config.project_root.clone(),
243	                tsconfig: config.tsconfig.clone(),
244	                tsc_path: config.tsc_path.clone(),
245	                targets: Vec::new(),
246	                request_timeout: config.request_timeout,
247	                expected_versions: config.expected_versions,
248	                record_to: None,
249	                extra_env: config.extra_env.clone(),
250	                reverse_queries: false,
251	                prepared_options: None,
252	            };
253	            let started = supervisor_config(&request).map_err(|reason| self.stay_down(reason))?;
254	            let supervisor = match Supervisor::spawn(started).await {
255	                Ok(supervisor) => supervisor,
256	                Err(error) => return Err(self.stay_down(error.to_string())),
257	            };
258	            // Initialize the session and read the compiler options once; every request after builds only its program.
259	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
260	            match Rpc::prepare(&supervisor.client(), config.request_timeout, tsconfig).await {
261	                Ok(options) => self.options = Some(options),
262	                Err(error) => {
263	                    supervisor.shutdown().await.ok();
264	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
265	                }
266	            }
267	            self.supervisor = Some(supervisor);
268	        }
269	        Ok(())
270	    }
271	
272	    fn stay_down(&mut self, reason: String) -> String {
273	        self.down = Some(reason.clone());
274	        reason
275	    }
276	
277	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
278	        if let Err(reason) = self.ensure(config).await {
279	            return SemanticOutcome::unavailable(reason);
280	        }
281	        let Some(supervisor) = self.supervisor.as_ref() else {
282	            return SemanticOutcome::unavailable("the checker is not running");
283	        };
284	        let mut request = SemanticRequest::new(config.project_root.clone(), targets);
285	        request.tsconfig = config.tsconfig.clone();
286	        request.tsc_path = config.tsc_path.clone();
287	        request.request_timeout = config.request_timeout;
288	        request.expected_versions = config.expected_versions;
289	        request.extra_env.clone_from(&config.extra_env);
290	        request.prepared_options.clone_from(&self.options);
291	        let outcome = answer_with(supervisor, &request).await;
292	        self.served += 1;
293	        outcome
294	    }
295	
296	    /// Replaces the process when it has built enough programs or grown past the memory bound. A planned replacement,
297	    /// not a crash: the next request starts a fresh process.
298	    async fn maintain(&mut self, config: &OnDemandConfig) {
299	        let Some(supervisor) = self.supervisor.as_ref() else { return };
300	        let worn = self.served >= MAX_REQUESTS_PER_PROCESS;
301	        let bloated = !worn
302	            && self.served.is_multiple_of(RSS_CHECK_EVERY)
303	            && supervisor.process_id().and_then(resident_mib).is_some_and(|mib| mib > config.max_rss_mib);
304	        if worn || bloated {
305	            if let Some(old) = self.supervisor.take() {
306	                old.shutdown().await.ok();
307	            }
308	            self.options = None;
309	            self.served = 0;
310	        }
311	    }
312	}
313	
