315	mod tests {
316	    use super::resident_mib;
317	
318	    #[test]
319	    fn a_running_process_has_resident_memory() {
320	        let mib = resident_mib(std::process::id()).expect("this process is listed");
321	        assert!((1..16_384).contains(&mib), "{mib} MiB");
322	    }
323	
324	    #[test]
325	    fn a_process_that_does_not_exist_has_none() {
326	        assert_eq!(resident_mib(u32::MAX - 1), None);
327	    }
